using System.ComponentModel.DataAnnotations;

namespace DocSummary.Models;

public class SummarizeRequest
{
    [Required]
    [MinLength(1)]
    public string DocumentText { get; set; } = string.Empty;

    [Range(1, 100)]
    public int MaxSentences { get; set; } = 3;
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public string Summary { get; set; } = string.Empty;
    public int OriginalLength { get; set; }
    public int SummaryLength { get; set; }
}

namespace DocSummary.Services;

public interface IDocumentSummarizer
{
    string Summarize(string documentText, int maxSentences);
}

namespace DocSummary.Services;

public class ExtractiveSummarizer : IDocumentSummarizer
{
    public string Summarize(string documentText, int maxSentences)
    {
        var sentences = SplitIntoSentences(documentText);
        if (sentences.Count <= maxSentences)
            return string.Join(" ", sentences);

        var scored = sentences
            .Select((sentence, index) => new { sentence, index, score = ScoreSentence(sentence, sentences) })
            .OrderByDescending(s => s.score)
            .Take(maxSentences)
            .OrderBy(s => s.index)
            .Select(s => s.sentence);

        return string.Join(" ", scored);
    }

    private static List<string> SplitIntoSentences(string text)
    {
        return text
            .Split(['.', '!', '?'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(s => s.Length > 0)
            .Select(s => s + ".")
            .ToList();
    }

    // Ranks sentences by word frequency — words appearing in many sentences signal importance.
    private static double ScoreSentence(string sentence, List<string> allSentences)
    {
        var words = GetWords(sentence);
        if (words.Count == 0)
            return 0;

        var allWords = allSentences.SelectMany(GetWords).ToList();
        var frequency = allWords
            .GroupBy(w => w)
            .ToDictionary(g => g.Key, g => g.Count());

        return words.Sum(w => frequency.GetValueOrDefault(w, 0)) / (double)words.Count;
    }

    private static List<string> GetWords(string text)
    {
        return text
            .Split([' ', '\t', '\n', '\r', ',', ';', ':', '"', '(', ')', '[', ']'],
                   StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Select(w => w.ToLowerInvariant())
            .Where(w => w.Length > 2)
            .ToList();
    }
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummaryController : ControllerBase
{
    private readonly IDocumentSummarizer _summarizer;

    public SummaryController(IDocumentSummarizer summarizer)
    {
        _summarizer = summarizer;
    }

    [HttpPost]
    public ActionResult<SummarizeResponse> Summarize([FromBody] SummarizeRequest request)
    {
        var summary = _summarizer.Summarize(request.DocumentText, request.MaxSentences);

        return Ok(new SummarizeResponse
        {
            Summary = summary,
            OriginalLength = request.DocumentText.Length,
            SummaryLength = summary.Length
        });
    }
}

